-- Passage rg4-main-idea-summary-p01
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('3d37c870-bc05-5ce0-9aa6-466eec1e5d78', 'rg4-main-idea-summary-p01', (select id from public.skills where slug = 'read-g4-main-idea-summary'), null,
        '3-5', $q$From Tree to Pancake$q$, $q$Maple syrup comes from the sap of maple trees. Making it takes careful work, lots of time, and the right kind of weather.

Sap starts to flow in late winter. The best days are warm and sunny, while the nights are still below freezing. This change in temperature pushes sap up and down inside the tree. Farmers watch the weather closely so they know when to begin.

To collect sap, a farmer drills a small hole in the trunk. A short tube called a tap goes into the hole. Sap drips out through the tap and into a bucket or a long plastic line. Fresh sap looks like water and tastes only a little sweet.

Next, the sap is boiled in a wide, flat pan. As it boils, the water turns to steam and floats away. The sap slowly gets thicker, darker, and sweeter. It takes about forty gallons of sap to make just one gallon of syrup.

Finally, the syrup is strained to remove bits of grit. Then it is poured into bottles while it is still hot. When you pour maple syrup on your pancakes, you are tasting weeks of patient work.$q$, 'draft')
