-- Passage rg4-main-idea-summary-p04
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('df25b1de-51c6-532d-8905-27034834ba3a', 'rg4-main-idea-summary-p04', (select id from public.skills where slug = 'read-g4-main-idea-summary'), null,
        '3-5', $q$The Bicycle Changes Over Time$q$, $q$The bicycles people ride today took many years to develop. Early inventors tried many ideas before they found a design that was safe and easy to ride.

One of the first bikes was built about two hundred years ago. It had two wheels and a seat, but no pedals. Riders sat on it and pushed along the ground with their feet. It was fun on smooth paths, but slow and hard on bumpy roads.

Later, makers added pedals to the front wheel. To go faster, they made the front wheel bigger and bigger. Some front wheels were taller than a grown person! These high bikes were fast, but riders sat far above the ground. A small rock could make a rider tumble forward.

Then came a design called the safety bicycle. Its two wheels were the same size. A chain connected the pedals to the back wheel. Riders sat lower, so they could put their feet on the ground. Soon, air-filled rubber tires made rides much smoother.

The safety bicycle quickly became popular. Workers rode to their jobs, and children rode to school. The basic shape of that bike is still used today, more than one hundred years later.$q$, 'draft')
on conflict (id) do update set title = excluded.title, body = excluded.body
where public.passages.status = 'draft';
