  ('1f41155c-eded-5987-954a-d31fa9d55d55', null, (select id from public.skills where slug = 'read-g4-text-structure'), null, 'hard',
   $q$Why does the author tell how frogs and toads are alike before telling how they are different?$q$, $q$[{"text":"To show that the author thinks toads make better pets than frogs","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"Because the passage is in time order and likenesses happened first","is_correct":false,"misconception_token":"wrong-structure"},{"text":"To show why they are easy to mix up, so the differences become useful clues","is_correct":true},{"text":"To prove that frogs and toads are really the very same animal","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$To show why they are easy to mix up, so the differences become useful clues$q$, $q$Paragraph 1 says they "look a lot alike" and then says "there are many ways to tell them apart," so the likenesses explain why the differences matter. The passage clearly says they are different, so they are not the same animal.$q$, 'draft', '611d0a78-c067-5026-b642-7ac624243ed9')
